INSERT IGNORE INTO `tour_transfer_prices` (`region`,`duty_code`,`location_type`,`point_a`,`point_b`,`route_description`,`service`,`distance_km`,`start_time`,`duration_min`,`day_schedule`,`valid_from`,`valid_to`,`vehicle`,`price`) VALUES
('old city tour + fountain square walking tour',NULL,'Hotel','Hotel','35',35,'Private Transfer',NULL,NULL,NULL,'10:00 – Leaving Hotel to Old City    - Old City tour starts from Shamakhi Gates followed by below places (Photo stop):  - Shamakhi Gates – The historic entrance to the Old City, showcasing iconic stone architecture.  - Sculptures of Azim Azimzadeh – Artistic monuments honoring Azerbaijan’s famed satirical painter and graphic artist.  - Caravanserai of Bukhara – A restored medieval inn once used by Silk Road traders for rest and trade.  - Caravanserai of Multani – A traditional guesthouse built for merchants from Multan, reflecting oriental caravan culture.  - Maiden’s Tower – Baku’s mysterious UNESCO-listed tower offering panoramic views of the Old City.  - Bazar Square – A lively historic square once serving as the commercial heart of Icherisheher.  - Miniature Books’ Museum – A unique museum displaying one of the world’s largest collections of tiny books.  - Shirvanshahs’ Palace – A majestic 15th-century royal complex showcasing medieval Azerbaijani architecture.   13:00 – Lunch Break   14:00 – Fountain Square walking tour (The square is a public   gathering place, especially after business hours and during the   weekend. It is an attractive tourist destination with many boutiques,  restaurants, shops, hotels and passage. This is one of the most  crowd and lively places in the city.)    18:00 – Dinner Break (if included)   19:00 –Drop to Hotel   Overnight in Baku',NULL,NULL,'Vito/Viano - 8 Seaters (English-Non fluent)',50.0),
